mapper.update:
UPDATE TB_BUSINESS
SET STATUS_CD = #{statusCd}
WHERE BIZ_NO = #{bizNo}

UPDATE TB_BUSINESS_AUTH
SET STATUS_CD = #{statusCd}
WHERE AUTH_ID = (
      SELECT AUTH_ID
        FROM TB_BUSINESS_AUTH
       WHERE BIZ_NO = #{bizNo}
       ORDER BY APPLY_DATE DESC
       FETCH FIRST 1 ROW ONLY
    )

UPDATE TB_BUSINESS_AUTH
SET STATUS_CD = #{statusCd},
    REJECT_REASON = #{rejectReason}
WHERE AUTH_ID = (
      SELECT AUTH_ID
        FROM TB_BUSINESS_AUTH
       WHERE BIZ_NO = #{bizNo}
       ORDER BY APPLY_DATE DESC
       FETCH FIRST 1 ROW ONLY
    )

mapper.select:
SELECT MEMBER_NO
FROM TB_MEMBER
WHERE MEMBER_ID = #{bizId}
   OR EMAIL = #{bizId}
FETCH FIRST 1 ROW ONLY

SELECT COUNT(*)
  FROM TB_COUPON
 WHERE APPROVAL_STATUS = #{approvalStatus}

SELECT C.COUPON_ID, C.COUPON_CODE, C.COUPON_NAME, C.COUPON_TYPE, C.DISCOUNT_VALUE, C.MIN_ORDER_AMT, C.TOTAL_BUDGET, C.ISSUED_BUDGET, C.TOTAL_QTY, C.ISSUED_QTY, C.USE_START_DATE, C.USE_END_DATE, C.BIZ_MEMBER_NO, C.APPROVAL_STATUS, C.REJECT_REASON, C.APPROVAL_DATE, C.STATUS_CD, C.REG_DATE, B.BIZ_NAME FROM TB_COUPON C LEFT JOIN TB_BUSINESS B ON B.BIZ_NO = C.BIZ_MEMBER_NO WHERE C.APPROVAL_STATUS = #{approvalStatus}
AND C.STATUS_CD = #{statusCd}
ORDER BY C.REG_DATE DESC

SELECT COUNT(*)
  FROM TB_COUPON
 WHERE APPROVAL_STATUS = #{approvalStatus}

   AND STATUS_CD = #{statusCd}
